"""Migration of legacy/opportunity_rules.vrl for OPP_MASTER validation."""

from decimal import Decimal
from typing import Any


def _value(record: dict | None, field: str) -> Any:
    """Return a field value, with missing and None behaving as empty string."""
    if record is None:
        return ""
    value = record.get(field, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    """Legacy NVL: empty string and None select the default."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion, where empty values compare as zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_ge(left: Any, right: Any) -> bool:
    """Legacy date >= comparison, including the 00000000 no-value sentinel."""
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # RULE OPP-001 ON OPP_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amt, 0)) >= Decimal("0")):
            errors.append(
                {"code": "E3001", "message": "Amount negative", "severity": "BLOCK"}
            )

    # RULE OPP-002 ON OPP_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal("0"):
            errors.append(
                {
                    "code": "E3002",
                    "message": "Won opportunity requires amount",
                    "severity": "BLOCK",
                }
            )

    # RULE OPP-003 ON OPP_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_rsn == "":
            errors.append(
                {
                    "code": "E3003",
                    "message": "Lost reason required",
                    "severity": "BLOCK",
                }
            )

    # RULE OPP-004 ON OPP_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and close_dt == "00000000":
            errors.append(
                {
                    "code": "E3004",
                    "message": "Won opportunity requires close date",
                    "severity": "BLOCK",
                }
            )

    # RULE OPP-005 ON OPP_MASTER WHEN UPDATE
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            errors.append(
                {
                    "code": "E3005",
                    "message": "Cannot reopen a won opportunity",
                    "severity": "BLOCK",
                }
            )

    # RULE OPP-006 ON OPP_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        stage_pct_number = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage_pct_number == Decimal("10"))
            or (stat_cd == "Q" and stage_pct_number == Decimal("25"))
            or (stat_cd == "N" and stage_pct_number == Decimal("60"))
            or (stat_cd == "W" and stage_pct_number == Decimal("100"))
            or (stat_cd == "L" and stage_pct_number == Decimal("0"))
        )
        if not valid_stage:
            errors.append(
                {
                    "code": "E3006",
                    "message": "Stage percent inconsistent with status",
                    "severity": "BLOCK",
                }
            )

    # RULE OPP-007 ON OPP_MASTER WHEN INSERT
    if event == "INSERT":
        valid_close_date = close_dt == "00000000" or _date_ge(close_dt, today)
        if not valid_close_date:
            errors.append(
                {
                    "code": "E3007",
                    "message": "Close date in past",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
